window.kbPageData["views/entry/k-6129abc029f16867"] = {"key":"entry/k-6129abc029f16867","state":{"route":"entry/k-6129abc029f16867"},"node":{"id":"k-6129abc029f16867","mode":"k","title":"多元化食物供给体系","type":"概念与词义","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2025 副省级 行测#6","国考 2025 地市级 行测#6","国考 2025 行政执法 行测#6"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":2,"reviewSet":"多题条目","independentCount":1,"tags":{"专题":["rural"],"主类":["概念与词义"],"出处性质":["机构注释"],"学科":["公共管理","政治理论"],"来源主题":["农业与城乡治理"],"资料类别":["非时政"]},"directorySummary":"多元化食物供给体系是在保障粮食供给的基础上，统筹利用农业、林业、牧业和渔业等资源，从多种途径提供食物的体系。","review":{"title":"多元化食物供给体系","type":"概念与词义","definition":"多元化食物供给体系是在保障粮食供给的基础上，统筹利用农业、林业、牧业和渔业等资源，从多种途径提供食物的体系。","explanation":"2024年《国务院办公厅关于践行大食物观构建多元化食物供给体系的意见》提出树立大农业观、大食物观，推动农林牧渔并举，将肉蛋奶、水产品、森林食品等纳入食物供给的统筹范围，以保障粮食和重要农产品稳定安全供给。","basis":"据关联原题及所列出处编释。","references":[{"source":"food","location":"总体要求"}],"related":["k-fbc703040a1d4d3a","k-10875ff0d8a54918","k-82a4f4b98ff57ecb"],"examFocus":{"国考 2025 副省级 行测#6":"对照粮食安全部署，核对各项举措涉及的食物供给、耕地建设、种业、进口和科技攻关要求。"}},"aspects":[{"title":"农林牧渔并举","uses":[{"unit":"Q1","role":"直接考查","use":"第②项将践行大食物观、推动农林牧渔并举列为保障粮食安全的举措，表述正确。本题①②③⑤正确，共4项，选C。","evidence":"树立大农业观、大食物观，农林牧渔并举，构建多元化食物供给体系","qids":["国考 2025 副省级 行测#6","国考 2025 地市级 行测#6","国考 2025 行政执法 行测#6"]}]}],"sources":[{"id":"9784754828cadfa9","label":"多元化食物供给体系","topic":"农业与城乡治理","category":"非时政","text":"3.元化食物供给\n《国务院办公厅关于践行大食物观构建多元化食物供给体系的意见》指出，树立大农业\n观、大食物观，农林牧渔并举，构建多元化食物供给体系，是党中央提出的明确要求，是\n保障粮食和重要农产品稳定安全供给的客观要求和重要举措。\n构建多元化食物供给体系，全方位、多途径开发食物资源，有利于更好满足人民群众日\n益多元化的食物消费需求，实现从“吃得饱”向“吃得好”升级。\n构建多元化食物供给体系有两层含义。一是拓宽食物供给渠道，提高食物来源结构的多\n元化水平。除了向耕地和植物动物要食物，还要进一步开发草原森林海洋资源，挖掘微生物\n和生物工程技术潜力，加强对非常规农业生产空间的开发和利用。二是增加食物供给种类，\n提高食物产品构成的多元化水平。除了粮食，还要增加肉类、蔬菜、水果、水产品等各类食\n物供给，既保障传统的以口粮为主的粮食安全，也保障肉蛋奶蔬果油糖等非口粮重要农产品\n的供给安全。","source":{"doc":"6cbfb01fe723bba64b75","first":34,"last":34,"page":34,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"国考 2025 副省级 行测#6":{"paper":"国考 2025 副省级 行测","n":6,"mod":"政治理论","src":["ffe12c35a46d4df574ec.pdf",1],"asrc":["ff0b352b44d417525086.pdf",2],"card":"ff24cb98d02636b69cd754bf","links":[{"id":"k-6129abc029f16867","role":"直接考查","why":"农林牧渔并举是保障粮食和重要农产品稳定安全供给的具体举措。"}]},"国考 2025 地市级 行测#6":{"paper":"国考 2025 地市级 行测","n":6,"mod":"政治理论","src":["31f401e91aef8d11365d.pdf",1],"asrc":["8cece062c7c079b53130.pdf",2],"card":"692576f7e1cbee543408917c","links":[{"id":"k-6129abc029f16867","role":"直接考查","why":"农林牧渔并举是保障粮食和重要农产品稳定安全供给的政策举措。"}]},"国考 2025 行政执法 行测#6":{"paper":"国考 2025 行政执法 行测","n":6,"mod":"政治理论","src":["d8efe4e19862104d89c8.pdf",1],"asrc":["e2c4b1970d2b49eac0fd.pdf",2],"card":"712cd85b1fc69bc908b841c9","links":[{"id":"k-6129abc029f16867","role":"直接考查","why":"农林牧渔并举是拓展食物来源、保障稳定供给的具体要求。"}]}},"terms":{"k-fbc703040a1d4d3a":{"id":"k-fbc703040a1d4d3a","mode":"k","type":"制度与规则","title":"乡村产业振兴","qs":[],"count":2},"k-10875ff0d8a54918":{"id":"k-10875ff0d8a54918","mode":"k","type":"制度与规则","title":"农业现代化的科技和改革双轮驱动","qs":[],"count":3},"k-82a4f4b98ff57ecb":{"id":"k-82a4f4b98ff57ecb","mode":"k","type":"制度与规则","title":"农业现代化与农村现代化","qs":[],"count":2}},"references":{"food":{"name":"国务院办公厅关于践行大食物观构建多元化食物供给体系的意见","url":"https://app.www.gov.cn/govdata/gov/202409/15/519551/article.html"}},"topics":[{"slug":"rural","title":"乡村振兴与粮食安全"}],"units":{"k-6129abc029f16867":[["国考 2025 副省级 行测#6","国考 2025 地市级 行测#6","国考 2025 行政执法 行测#6"]]}};
